@Scheme.exists_homogeneous_pos_mem_notMem : ∀ {σ : Type u_2} {A : Type u_1} [inst : CommRing A] [inst_1 : SetLike σ A]
  [inst_2 : AddSubgroupClass σ A] (𝒜 : ℕ → σ) [inst_3 : GradedRing 𝒜] {I p : Ideal A} [hp : p.IsPrime],
  Ideal.IsHomogeneous 𝒜 I →
    ¬(HomogeneousIdeal.irrelevant 𝒜).toIdeal ≤ p → ¬I ≤ p → ∃ m f, 0 < m ∧ f ∈ 𝒜 m ∧ f ∈ I ∧ f ∉ p
@Scheme.exists_homogeneous_pos_mem_forall_notMem : ∀ {σ : Type u_2} {A : Type u_1} [inst : CommRing A]
  [inst_1 : SetLike σ A] [inst_2 : AddSubgroupClass σ A] (𝒜 : ℕ → σ) [inst_3 : GradedRing 𝒜] {ι : Type u_3}
  (s : Finset ι) (p : ι → Ideal A),
  (∀ i ∈ s, (p i).IsPrime) →
    (∀ i ∈ s, Ideal.IsHomogeneous 𝒜 (p i)) →
      (∀ i ∈ s, ¬(HomogeneousIdeal.irrelevant 𝒜).toIdeal ≤ p i) →
        ∀ {I : Ideal A},
          Ideal.IsHomogeneous 𝒜 I →
            (∀ i ∈ s, ¬I ≤ p i) → (∃ m f, 0 < m ∧ f ∈ 𝒜 m ∧ f ∈ I) → ∃ M f, 0 < M ∧ f ∈ 𝒜 M ∧ f ∈ I ∧ ∀ i ∈ s, f ∉ p i
@Scheme.exists_homogeneous_pos_mem_forall_notMem_of_antichain : ∀ {σ : Type u_2} {A : Type u_1} [inst : CommRing A]
  [inst_1 : SetLike σ A] [inst_2 : AddSubgroupClass σ A] (𝒜 : ℕ → σ) [inst_3 : GradedRing 𝒜] (T : Finset (Ideal A)),
  (∀ q ∈ T, q.IsPrime) →
    (∀ q ∈ T, Ideal.IsHomogeneous 𝒜 q) →
      (∀ q ∈ T, ¬(HomogeneousIdeal.irrelevant 𝒜).toIdeal ≤ q) →
        (∀ q ∈ T, ∀ q' ∈ T, q ≠ q' → ¬q ≤ q') →
          ∀ {I : Ideal A},
            Ideal.IsHomogeneous 𝒜 I →
              (∀ q ∈ T, ¬I ≤ q) → (∃ m f, 0 < m ∧ f ∈ 𝒜 m ∧ f ∈ I) → ∃ M h, 0 < M ∧ h ∈ 𝒜 M ∧ h ∈ I ∧ ∀ q ∈ T, h ∉ q
@Scheme.Ideal.IsHomogeneous.finsetInf : ∀ {σ : Type u_2} {A : Type u_1} [inst : CommRing A] [inst_1 : SetLike σ A]
